export default pattern<IframeSharedLedgerInput, IframeSharedLedgerOutput>(({
  input,
  state,
  output,
}) => {
  const { table } = cfSqlite;
  const iframeDatabase0Tables = {
    ["entries"]: table({
      ["id"]: "integer primary key",
      ["memo"]: "text not null",
      ["amount"]: "real not null",
      ["category"]: "text not null",
    }),
  };
  const iframeDatabase0 = sqliteDatabase({ tables: iframeDatabase0Tables });
  const context = IframeContext({
    input,
    state,
    output,
    ["ledgerDatabase"]: iframeDatabase0,
  });

  return {
    [NAME]: "Iframe · Shared SQLite ledger",
    [UI]: (
      <div style={{ width: "100%", height: "760px" }}>
        <cf-iframe
          src={GUEST_HTML}
          $context={context}
          resourceKinds={{
            input: "readonly",
            ["ledgerDatabase"]: "sqlite",
          } as const}
        />
      </div>
    ),
    state,
    output,
  };
});
